actions.script:
success = false
errorMessage = null
profile = profileName
responseContent = null
boolean txSuspended = false

if (ec.transaction.isTransactionInPlace()) {
    txSuspended = ec.transaction.suspend()
}

long start = System.currentTimeMillis()
try {
    def client = (profileName && profileName != "default") ? ec.llm.getClient(profileName) : ec.llm.getDefault()
    if (client == null) {
        errorMessage = "Could not obtain LlmClient for profile: ${profileName}"
        return
    }

    def response = client
            .system(systemPrompt)
            .user(userPrompt)
            .call()

    durationMs = System.currentTimeMillis() - start
    responseContent = response?.getContent() ?: response?.toString()
    success = true
} catch (Exception e) {
    durationMs = System.currentTimeMillis() - start
    errorMessage = e.getMessage()
    ec.logger.error("Error executing test#LlmClient for [${profileName}]: ${e.message}", e)
} finally {
    if (txSuspended) {
        ec.transaction.resume()
    }
}

results = []
for (String pName in ["ollama", "gemini"]) { Map testRes = ec.service.sync().name("org.moqui.ide.LlmClientServices.test#LlmClient") .parameters([ profileName: pName, userPrompt: "Confirm connection and report active model name." ]) .call()
results.add([ profile: pName, success: testRes.success, durationMs: testRes.durationMs, response: testRes.responseContent, error: testRes.errorMessage ]) }
